// Declaración responsable del productor del SIF (art. 13 RD 1007/2023; art. 15 Orden HAC/1177/2024).
// declaracion-responsable.json and public/declaracion-responsable/*.txt are GENERATED by
// factuio-api/scripts/sif-declaration/release-declaration.mjs (--portal-dir): never edit them by hand.
// The declaration text is the legal text; this module only adds the page copy around it.
import bundleJson from "./declaracion-responsable.json";

export interface DeclarationItem { label: string; value: string }
export interface DeclarationSection { key: string; label: string | null; value: string | null; items?: DeclarationItem[] | null }
export interface Declaration {
  version: string;
  issued_on: string;
  title: string;
  sections: DeclarationSection[];
  annex: DeclarationSection[];
  text: string;
  text_file: string;
  /** Identity the AEAT XML SistemaInformatico block carries for this version (producer = 1.h/1.i). */
  system?: {
    name: string; id_code: string; verifactu_only: string; multiple_taxpayers: string;
    producer?: { name: string; nif: string | null; id_otro: { country_code: string; id_type: string; id: string } | null };
  };
  /**
   * Public summary of the VERI*FACTU conformance gate for this version: whether the Maven gate
   * passed, the version and the date. The raw gate (command, classes) is never published here.
   */
  gate?: { passed: boolean; version: string; date: string };
}
export interface DeclarationBundle { schema_version: number; current: string | null; versions: Declaration[] }

export const declarationBundle = bundleJson as DeclarationBundle;

export function currentDeclaration(bundle: DeclarationBundle = declarationBundle): Declaration | null {
  return bundle.versions.find((v) => v.version === bundle.current) ?? null;
}

/** Public URL of a version's plain-text file (basePath-aware: public/ files bypass next/link). */
export function declarationTextHref(d: Declaration): string {
  return `${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/declaracion-responsable/${d.text_file}`;
}

